/* --- pots as variable parts (mirror of preamp.py::pot_values) ------------ */
#define BN_PREAMP2203_N_POTS 9
/* the HIGH/LOW input jack contacts as variable parts (Woodbury update, no re-init):
 * values per mode in BN_PREAMP2203_JACK_HIGH/LOW (R_ON = 1, R_OFF = 1e9) */
#define BN_PREAMP2203_N_JACK 4
static const int BN_PREAMP2203_JACK_IDX[BN_PREAMP2203_N_JACK] =
    { 2, 3, 4, 5 };
static const double BN_PREAMP2203_JACK_HIGH[BN_PREAMP2203_N_JACK] =
    { 1.0, 1000000000.0, 1.0, 1000000000.0 };
static const double BN_PREAMP2203_JACK_LOW[BN_PREAMP2203_N_JACK] =
    { 1000000000.0, 1.0, 1000000000.0, 1.0 };
static const int BN_PREAMP2203_POT_IDX[BN_PREAMP2203_N_POTS] =
    { 18, 19, 20, 21, 22, 23, 24, 25, 26 };

/* The same laws and EPS as the prototype:
 *   VR1 volume, VR5 bass and VR2 master -> the TWO-SEGMENT audio taper: a knee at 60 % of the travel passing 12 %,
 *     which gives 10 % at mid travel (the classic audio-taper specification). VR2 is the same physical part
 *     (1 M log) as VR1, so it uses the same law (bn_pot_log_master below).
 *   VR3 treble and VR4 middle -> linear, as in the schematic. */
#define BN_POT_A    0.12
#define BN_POT_CODO 0.60
#define BN_POT_W    0.05     /* half width of the knee's fillet */
/* An EXACT mirror of dsp/prototype/preamp.py::_pot_log. The two segments are kept intact outside +-BN_POT_W;
 * inside, the corner is rounded by SMOOTHING THE SLOPE AND INTEGRATING IT. Blending the two lines (the obvious way)
 * gives a NON-MONOTONIC law, because they cross at the knee and diverge: the knob would go backwards. Here
 * f' = m1 + (m2 - m1) * smoothstep >= m1 > 0, monotonic by construction, and it lands exactly on the segments at
 * the edges of the fillet. Why round it at all: a sharp corner makes d(resistance)/dt jump x11 as the knob crosses
 * it, which is an audible transient when the knob is turned with no signal. */
static inline double bn_pot_log(double x)
{
    const double m1 = BN_POT_A / BN_POT_CODO;
    const double m2 = (1.0 - BN_POT_A) / (1.0 - BN_POT_CODO);
    if (x <= BN_POT_CODO - BN_POT_W) { return m1 * x; }
    if (x >= BN_POT_CODO + BN_POT_W) { return BN_POT_A + m2 * (x - BN_POT_CODO); }
    const double f1 = m1 * (BN_POT_CODO - BN_POT_W);
    const double t  = (x - (BN_POT_CODO - BN_POT_W)) / (2.0 * BN_POT_W);
    return f1 + m1 * (x - (BN_POT_CODO - BN_POT_W))
              + (m2 - m1) * 2.0 * BN_POT_W * (t * t * t - 0.5 * t * t * t * t);
}
/* The MASTER uses the SAME law as VR1/VR5: it is the same physical part (1 M log in the schematic). Kept as its
 * own function so callers name what they mean. Mirror of dsp/prototype/preamp.py::_pot_log_master. */
static inline double bn_pot_log_master(double x) { return bn_pot_log(x); }

/* The export (6550) version's preamp fits a Treble pot of 250 k and a Middle pot of 25 k where the standard one
 * uses 220 k / 22 k. The pots are variable parts of the DK solve (Woodbury, no re-init), so the version just
 * feeds a different maximum resistance -- no second matrix. `us` = the us_spec port flag. */
static inline void bn_preamp2203_pot_values(
    double vol, double treb, double bass, double mid, double master,
    double out[BN_PREAMP2203_N_POTS], int us)
{
    const double EPSR = 1.0;
    const double VR3 = us ? 250000.0 : 220000.0;   /* treble (dsp/prototype/preamp.py) */
    const double VR4 = us ? 25000.0 : 22000.0;    /* middle */
    const double v = bn_pot_log(vol), b = bn_pot_log(bass),
                 m = bn_pot_log_master(master);
    out[0] = 1e6   * (1.0 - v);    out[1] = 1e6   * v;        /* VR1 vol    */
    out[2] = VR3   * (1.0 - treb); out[3] = VR3   * treb;     /* VR3 treble */
    out[4] = 1e6   * b;                                       /* VR5 bass   */
    out[5] = VR4   * (1.0 - mid);  out[6] = VR4   * mid;      /* VR4 middle */
    out[7] = 1e6   * (1.0 - m);    out[8] = 1e6   * m;        /* VR2 master */
    for (int k = 0; k < BN_PREAMP2203_N_POTS; ++k) {
        if (out[k] < EPSR) { out[k] = EPSR; }
    }
}

#endif /* BN_PREAMP2203_H */
